#!/usr/bin/env python3
"""dataset_stats.json -> dataset_stats.md (tables for REPORT.md)."""
import json, numpy as np, pandas as pd
OUT = '/root/rasr-pairuav/outputs/supp/trackD'; S = json.load(open(f'{OUT}/dataset_stats.json')); c = S['camera']; L = []
row = lambda name, d, f='.2f': f"| {name} | {d['min']:{f}} | {d['p1']:{f}} | {d['p5']:{f}} | {d['p25']:{f}} | {d['p50']:{f}} | {d['p75']:{f}} | {d['p95']:{f}} | {d['p99']:{f}} | {d['max']:{f}} | {d['mean']:{f}} | {d['std']:{f}} |"
H = '| quantity | min | p1 | p5 | p25 | p50 | p75 | p95 | p99 | max | mean | std |\n|---|' + '---:|' * 11
L += ['## Dataset statistics read from the released metadata\n', f"{S['buildings']} buildings x 150 cameras = {S['cameras']:,} cameras; {S['selected_pairs']:,} selected directed pairs (1,000 per building) = {100 * S['selected_fraction']:.2f} % of the {S['candidates_vs_selected']['candidates']:,} directed camera pairs (22,350 per building).\n",
      f"Label reconstruction from the KML files (ECEF difference rotated to east-north-up at the building anchor): max abs difference to the released labels over all selected pairs: x {S['label_reconstruction_max_abs_error']['x']:.1e} m, y {S['label_reconstruction_max_abs_error']['y']:.1e} m, z {S['label_reconstruction_max_abs_error']['z_enu_up']:.1e} m, tilt {S['label_reconstruction_max_abs_error']['tilt']:.1e} deg, heading {S['label_reconstruction_max_abs_error']['heading']:.1e} deg.\n",
      '### Cameras (all buildings)\n', H, row('height above terrain at the building anchor (m)', c['height_above_terrain_m']), row('tilt from nadir (deg)', c['tilt_deg']), row('heading (deg, clockwise from north)', c['heading_deg'], '.1f'),
      row('east offset from the anchor (m)', c['camera_offset_from_anchor_east_m']), row('north offset from the anchor (m)', c['camera_offset_from_anchor_north_m']), row('per-building mean height (m)', c['building_mean_height_m'], '.3f'),
      row('per-building height range (m)', c['within_building_height_range_m']), row('per-building east extent (m)', c['within_building_east_extent_m']), row('per-building north extent (m)', c['within_building_north_extent_m']), row('per-building largest camera-to-camera distance (m)', c['within_building_max_pair_distance_m']),
      f"\nRoll is 0 for every camera. Height = KML absolute altitude minus `anchor.terrain_altitude_msl` (terrain altitude below the building anchor, method string in the files: \"{list(S['screening']['terrain_method'])[0]}\"); it is a height above the terrain at the anchor, not above roofs. "
      f"Cameras per 30-degree heading sector: {c['heading_hist_12']}; per 5-degree tilt bin (0-45): {c['tilt_hist_9']}.\n",
      '### Pose differences: selected pairs vs all camera pairs\n', '| component | selected: min | p5 | p50 of abs | p95 | max | all pairs: min | p5 | p50 of abs | p95 | max | share of all pairs inside the selected range |', '|---|' + '---:|' * 11]
a, b, cv = S['selected_pairs_labels'], S['all_candidate_pairs_labels'], S['candidates_vs_selected']
for k, lab in (('x', 'dx east (m)'), ('y', 'dy north (m)'), ('z', 'dz up (m)'), ('tilt', 'd tilt (deg)'), ('heading', 'd heading (deg)')):
    L.append(f"| {lab} | {a[k]['min']:.2f} | {a[k]['p5']:.2f} | {a['abs_' + k]['p50']:.2f} | {a[k]['p95']:.2f} | {a[k]['max']:.2f} | {b[k]['min']:.2f} | {b[k]['p5']:.2f} | {b['abs_' + k]['p50']:.2f} | {b[k]['p95']:.2f} | {b[k]['max']:.2f} | {100 * cv['fraction_of_all_candidates_inside_range_per_component'][k]:.1f} % |")
L.append(f"| baseline length (m) | {a['dist']['min']:.2f} | {a['dist']['p5']:.2f} | {a['dist']['p50']:.2f} | {a['dist']['p95']:.2f} | {a['dist']['max']:.2f} | {b['dist']['min']:.2f} | {b['dist']['p5']:.2f} | {b['dist']['p50']:.2f} | {b['dist']['p95']:.2f} | {b['dist']['max']:.2f} | - |")
L.append(f"\n{100 * cv['fraction_of_all_candidates_inside_all_five_ranges']:.1f} % of all camera pairs lie inside the selected ranges on all five components (the selected pairs have |dx|, |dy| <= 15 m while camera positions span a 30 m x 30 m box, so |dx|, |dy| reach 30 m); the selected pairs are {100 * cv['selected_over_candidates_inside_all_ranges']:.1f} % of those.\n")
bl = S['balancing']; L.append(f"Balancing: pair ids name {bl['groups']} groups of buildings ({bl['buildings_per_group']}). Within a group, the counts of five equal-width bins of a component differ by at most (median over groups / max over groups, as a fraction of the group size): " + ', '.join(f"{k} {100 * v['median_relative_spread_of_5_bin_counts']:.2f} % / {100 * v['max']:.2f} %" for k, v in bl['five_equal_width_bins_within_group'].items()) + '.\n')
sc = S['screening']; L += ['### Screening statistics stored with every selected pair\n', '| field | min | p1 | p5 | p25 | p50 | p75 | p95 | p99 | max | mean | std |', '|---|' + '---:|' * 11, row('matches', sc['matches'], '.0f'), row('inliers', sc['inliers'], '.0f'), row('inlier_ratio', sc['inlier_ratio'], '.3f'), row('hull_fraction', sc['hull_fraction'], '.3f'), row('grid_cells', sc['grid_cells'], '.0f'),
      f"\n`model`: {sc['model_counts']}; `visual_screen`: {sc['visual_screen_strings']}. Pairs with exactly 20 inliers exist and {100 * sc['grid_cells_counts']['4'] / S['selected_pairs']:.1f} % of the pairs have exactly 4 occupied grid cells (maximum 16): the stored minima (matches >= {sc['minima']['matches']:.0f}, inliers >= {sc['minima']['inliers']:.0f}, grid_cells >= {sc['minima']['grid_cells']:.0f}) are consistent with acceptance thresholds of 20 inliers and 4 of 16 grid cells; "
      f"smallest stored inlier_ratio {sc['minima']['inlier_ratio']:.3f}, smallest hull_fraction {sc['minima']['hull_fraction']:.3f}. Share of selected pairs with fewer than 30 / 50 / 100 inliers: {100 * sc['share_below']['inliers_lt_30']:.1f} / {100 * sc['share_below']['inliers_lt_50']:.1f} / {100 * sc['share_below']['inliers_lt_100']:.1f} %. The files contain no field about human annotation."]
open(f'{OUT}/dataset_stats.md', 'w').write('\n'.join(L) + '\n'); print('\n'.join(L))
